css:
.print-format { padding: 0 !important; max-width: 80mm; }
.pos-receipt { width: 72mm; margin: 0 auto; font-family: "Inter", "Tajawal", "Noto Sans Arabic", Arial, sans-serif; font-size: 11.5px; color: #10231f; line-height: 1.35; }
.pos-receipt table { width: 100%; border-collapse: collapse; }
.pos-receipt td { padding: 1px 0; vertical-align: top; }
.pos-receipt .r-head { text-align: center; }
.pos-receipt .r-logo { max-height: 40px; max-width: 60mm; margin-bottom: 4px; }
.pos-receipt .r-name { font-size: 15px; font-weight: 700; }
.pos-receipt .r-name-ar { font-size: 13px; font-weight: 600; }
.pos-receipt .r-meta { font-size: 10.5px; color: #45554f; }
.pos-receipt .r-rule { border-top: 1px dashed #8a9a95; margin: 6px 0; }
.pos-receipt .r-end { text-align: end; white-space: nowrap; }
.pos-receipt .r-sub { color: #45554f; }
.pos-receipt .r-batch { font-size: 10px; color: #63736f; padding-bottom: 3px; }
.pos-receipt .r-grand td { font-size: 14px; font-weight: 700; padding-top: 3px; }
.pos-receipt .r-flag { text-align: center; font-weight: 700; letter-spacing: 0.08em; }
.pos-receipt .r-foot { text-align: center; font-size: 10.5px; white-space: pre-line; }
.pos-receipt .r-powered { text-align: center; font-size: 9px; color: #8a9a95; margin-top: 6px; }
@media print { @page { size: 80mm auto; margin: 3mm; } }
